export const VERILOG_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/verilog-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getVerilogStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(VERILOG_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
